<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import type {EChartsOption} from 'echarts'
import {api} from '../api'
import type {Exploration,ExplorationDetails} from '../exploration'
import {gameName} from '../gameNames'
import {compactChartNumber} from '../chartNumbers'
import DataChart from './DataChart.vue'

const props=defineProps<{tab:string;server:string;base:Exploration}>()
const data=ref<ExplorationDetails>(),error=ref(''),busy=ref(false),runtimeMetric=ref('host_cpu'),chosen=ref<string[]>([])
let controller:AbortController|undefined
async function load(){controller?.abort();const request=new AbortController();controller=request;data.value=undefined;busy.value=true;error.value='';
 try{const result=await api<ExplorationDetails>('/statistics/exploration/extended?'+new URLSearchParams({serverId:props.server,from:props.base.from,to:props.base.to}),{signal:request.signal});if(!request.signal.aborted){data.value=result;chosen.value=result.players.slice(0,3).map(p=>p.player)}}catch(e){if(!request.signal.aborted)error.value=e instanceof Error?e.message:'图表读取失败'}finally{if(controller===request)busy.value=false}}
watch(()=>[props.server,props.base.from,props.base.to,props.base.generatedAt],load,{immediate:true})
onBeforeUnmount(()=>controller?.abort())
const tip={trigger:'item' as const,renderMode:'richText' as const,confine:true}
const days=computed(()=>{const list:string[]=[];for(let d=Date.parse(props.base.from+'T00:00:00Z');d<=Date.parse(props.base.to+'T00:00:00Z');d+=86400000)list.push(new Date(d).toISOString().slice(0,10));return list})
const activities=[{name:'建筑',keys:['blocks.placed'],unit:'次',scale:1},{name:'挖掘',keys:['blocks.mined'],unit:'次',scale:1},{name:'种植',keys:['crops.planted'],unit:'次',scale:1},{name:'收获',keys:['crops.harvested'],unit:'次',scale:1},{name:'探索',keys:['travel.walk_millimeters','travel.swim_millimeters','travel.fly_millimeters','travel.glide_millimeters','travel.vehicle_millimeters'],unit:'米',scale:.001}]
const riverData=computed(()=>activities.map(a=>{const raw=days.value.map(day=>{const rows=data.value?.daily.filter(r=>r.day===day&&a.keys.includes(r.metric))??[];return rows.length?rows.reduce((s,r)=>s+Number(r.amount),0)*a.scale:null});const max=Math.max(0,...raw.map(v=>v??0));return {...a,raw,values:raw.map(v=>max>0?Math.round((v??0)/max*1000)/10:0)}}))
const river=computed<EChartsOption>(()=>({useUTC:true,tooltip:{...tip,formatter:(p:any)=>{const d=p.data,day=new Date(d[0]).toISOString().slice(0,10),series=riverData.value.find(a=>a.name===d[2])!,value=series.raw[days.value.indexOf(day)];return `${day} · ${series.name}\n${value==null?'无记录':value.toLocaleString()+' '+series.unit}\n相对强度 ${d[1]}`}},legend:{type:'scroll',top:0},singleAxis:{type:'time',min:Date.parse(props.base.from+'T00:00:00Z'),max:Date.parse(props.base.to+'T00:00:00Z')+(days.value.length===1?86399999:0),top:50,bottom:45,left:25,right:25,axisLabel:{hideOverlap:true,formatter:(v:number)=>new Date(v).toISOString().slice(5,10)}},series:[{type:'themeRiver',label:{show:false},data:riverData.value.flatMap(a=>days.value.flatMap((day,i)=>(days.value.length===1?[0,86399999]:[0]).map(offset=>[Date.parse(day+'T00:00:00Z')+offset,a.values[i]!,a.name] as [number,number,string])))}]}))
const clockRows=computed(()=>Array.from({length:168},(_,i)=>{const hour=i%24,weekday=Math.floor(i/24);return [hour,weekday,(props.base.hours.find(r=>r.hour===hour&&r.weekday===weekday)?.millis??0)/3600000]}))
const clock=computed<EChartsOption>(()=>({tooltip:{...tip,formatter:(p:any)=>`周${'一二三四五六日'[p.value[1]]} ${p.value[0]}:00\n${p.value[2]>0?'估算在线 '+p.value[2].toFixed(2)+' 人时':'没有在线记录'}`},visualMap:{min:0,max:Math.max(1,...clockRows.value.map(r=>r[2]!)),dimension:2,orient:'horizontal',left:'center',bottom:0,inRange:{color:['#edf5f0','#76cbb2','#15745c']}},series:[{type:'custom',coordinateSystem:'none',data:clockRows.value,renderItem:(_params:any,api:any)=>{const hour=Number(api.value(0)),day=Number(api.value(1)),size=Math.min(api.getWidth()-70,api.getHeight()-105),outer=size/2,inner=outer*.22,step=(outer-inner)/7,cx=api.getWidth()/2,cy=(api.getHeight()-30)/2;const start=hour*Math.PI/12-Math.PI/2,end=(hour+1)*Math.PI/12-Math.PI/2,children:any[]=[{type:'sector',shape:{cx,cy,r0:inner+day*step,r:inner+(day+1)*step-1,startAngle:start+.006,endAngle:end-.006},style:{fill:api.visual('color')}}];if(day===6&&hour%3===0)children.push({type:'text',style:{x:cx+Math.cos(start)*(outer+18),y:cy+Math.sin(start)*(outer+18),text:String(hour),align:'center',verticalAlign:'middle',fill:'#45665a',fontSize:12}});return {type:'group',children}}}]}))
const bubble=computed<EChartsOption>(()=>({tooltip:{...tip,formatter:(p:any)=>`${p.data.name}\n在线 ${p.value[0].toFixed(2)} 小时\n放置 ${p.value[1].toLocaleString()} 次\n挖掘 ${p.value[2].toLocaleString()} 次`},grid:{left:65,right:35,top:35,bottom:55},xAxis:{type:'value',name:'在线小时',nameLocation:'middle',nameGap:30,min:0,axisLabel:{hideOverlap:true}},yAxis:{type:'value',name:'放置次数',axisLabel:{formatter:compactChartNumber}},dataZoom:[{type:'inside',filterMode:'none'}],series:[{type:'scatter',data:data.value?.players.map(p=>({name:p.name,value:[Number(p.online)/3600000,Number(p.placed),Number(p.mined)]})),symbolSize:(v:any)=>12+Math.min(48,Math.sqrt(v[2]/Math.max(1,...(data.value?.players??[]).map(p=>Number(p.mined))))*48),itemStyle:{opacity:.65},emphasis:{label:{show:true,formatter:'{b}'}}}]}))
function compactBranches(rows:any[]):any[]{const sum=(node:any):number=>node.children?node.children.reduce((n:number,c:any)=>n+sum(c),0):Number(node.value);const sorted=rows.map(n=>({...n,value:sum(n)})).sort((a,b)=>b.value-a.value),top=sorted.slice(0,8).map(n=>n.children?{...n,children:compactBranches(n.children)}:n);if(sorted.length>8)top.push({name:'其他（合并）',value:sorted.slice(8).reduce((n,c)=>n+c.value,0)});return top}
const sunburst=computed<EChartsOption>(()=>{const projects=new Map<string,any>();for(const c of props.base.contributions.filter(c=>c.operation==='PLACE')){let project=projects.get(c.project);if(!project){project={name:c.project_name,players:new Map()};projects.set(c.project,project)}let player=project.players.get(c.player);if(!player){player={name:c.player_name,blocks:new Map()};project.players.set(c.player,player)}player.blocks.set(c.block,(player.blocks.get(c.block)??0)+Number(c.value))}const top=[...projects.values()].map(p=>({name:p.name,children:[...p.players.values()].map((u:any)=>({name:u.name,children:[...u.blocks].map(([b,v]:any)=>({name:gameName(b,'block')??b,value:v})).sort((a,b)=>b.value-a.value)}))}));return {tooltip:{...tip,formatter:(p:any)=>`${p.treePathInfo.slice(1).map((n:any)=>n.name).join(' → ')}\n${Number(p.value??0).toLocaleString()} 次放置`},series:[{type:'sunburst',radius:['8%','92%'],nodeClick:'rootToNode',sort:'desc',label:{rotate:'tangential',minAngle:24,fontSize:11,width:60,overflow:'truncate'},data:[{name:data.value?.serverName??'服务器',label:{rotate:0,formatter:'服务器',fontSize:11},children:compactBranches(top)}]}]}})
const runtimeLabels:Record<string,[string,string]>={host_cpu:['整机 CPU','%'],host_memory:['整机内存使用','%'],tps:['游戏流畅度','TPS'],cpu:['游戏进程 CPU','%'],memory:['游戏进程内存','MiB'],interval:['采样内最长帧间隔','毫秒']}
const runtimeRows=computed(()=>data.value?.runtime.filter(r=>r.metric===runtimeMetric.value)??[])
const box=computed<EChartsOption>(()=>({tooltip:{...tip,formatter:(p:any)=>{const r=runtimeRows.value[p.dataIndex];return r?`${r.day} · ${r.samples.toLocaleString()} 次采样\n最大 ${r.maximum.toFixed(2)}\n75% ${r.q3.toFixed(2)}\n中位 ${r.median.toFixed(2)}\n25% ${r.q1.toFixed(2)}\n最小 ${r.minimum.toFixed(2)} ${runtimeLabels[r.metric]?.[1]??''}`:''}},grid:{left:62,right:25,top:35,bottom:55},xAxis:{type:'category',data:runtimeRows.value.map(r=>r.day.slice(5)),axisLabel:{hideOverlap:true}},yAxis:{type:'value',name:runtimeLabels[runtimeMetric.value]?.[1]},series:[{type:'boxplot',data:runtimeRows.value.map(r=>[r.minimum,r.q1,r.median,r.q3,r.maximum]),itemStyle:{color:'#c7e7d9',borderColor:'#238464'}}]}))
const eventLabels:Record<string,string>={SERVER_START:'登记开服',PROJECT_START:'工程开工／继续',PROJECT_END:'工程完工',BACKUP:'世界备份'}
const eventTime=(at:string)=>new Intl.DateTimeFormat('zh-CN',{timeZone:props.base.zone,dateStyle:'short',timeStyle:'short',hour12:false}).format(new Date(at))
const timeline=computed<EChartsOption>(()=>({tooltip:{...tip,formatter:(p:any)=>`${p.data.name}\n${eventLabels[p.data.kind]}${p.data.revision?' · 第 '+p.data.revision+' 阶段':''}\n${eventTime(p.data.at)}`},grid:{left:110,right:30,top:30,bottom:80},xAxis:{type:'time',axisLabel:{hideOverlap:true,formatter:(v:number)=>new Intl.DateTimeFormat('zh-CN',{timeZone:props.base.zone,month:'2-digit',day:'2-digit'}).format(v)}},yAxis:{type:'category',data:Object.values(eventLabels),axisLabel:{width:95,overflow:'truncate'}},dataZoom:[{type:'slider',bottom:10},{type:'inside'}],series:[{type:'scatter',symbol:'diamond',symbolSize:14,data:data.value?.milestones.map(e=>({...e,value:[Date.parse(e.at),eventLabels[e.kind]],itemStyle:{color:['#259875','#728bde','#b18ada','#e5ad51'][Object.keys(eventLabels).indexOf(e.kind)]}}))}]}))
const radarAxes=[['placed','建筑'],['mined','挖掘'],['planted','种植'],['harvested','收获'],['travel','探索'],['chat','交流']] as const
const radar=computed<EChartsOption>(()=>{const players=data.value?.players??[],maxima=radarAxes.map(([key])=>Math.max(1,...players.map(p=>Number(p[key]))));return {tooltip:{...tip},legend:{type:'scroll',bottom:0},radar:{radius:'65%',indicator:radarAxes.map(([,name])=>({name,max:100})),splitArea:{areaStyle:{color:['#f6faf8','#eef5f2']}}},series:[{type:'radar',areaStyle:{opacity:.1},data:players.filter(p=>chosen.value.includes(p.player)).slice(0,3).map(p=>({name:p.name,value:radarAxes.map(([key],i)=>Math.round(Number(p[key])/maxima[i]!*1000)/10)}))}]}})
const options=computed(()=>({river:river.value,clock:clock.value,bubble:bubble.value,sunburst:sunburst.value,box:box.value,timeline:timeline.value,radar:radar.value}[props.tab]))
const titles:Record<string,string>={river:'活动河流',clock:'服务器时钟',bubble:'玩家气泡',sunburst:'施工旭日',box:'运行分布',timeline:'成长时间轴',radar:'玩家雷达'}
const explanations:Record<string,string>={river:'每类活动按所选日期内自己的峰值换算为 0–100，比较变化节奏，不表示在线时间占比。探索以估算距离计算；悬停看原始次数或米数。空白日期按无记录处理；仅选一天时显示当天总量，不能据此判断日内变化。',clock:'从内到外依次为周一至周日，顶部是 0 点，顺时针走过 24 小时。颜色表示所选日期累计的估算在线人时。',bubble:'横轴为在线小时，纵轴为放置次数，气泡越大表示挖掘越多。重叠时可以放大查看，不代表玩家能力排名。',sunburst:'从中心向外：服务器 → 工程 → 玩家 → 材料。点击扇区逐层展开，点击中心返回。统计累计放置次数，重叠工程可能分别计入。每层保留前 8 项，其余合并为“其他”，总次数保留。',box:'箱体显示中间一半采样及中位数，上下须线是观测最大和最小值。只有少数采样时不能代表长期表现。先看整机，再与游戏进程对比；缺少的采样不会补零。',timeline:'记录档案登记的开服日期、工程各阶段的开始/完成、已验证备份。拖动底部滑块查看时间细节；登记日期不是实测开机时间。',radar:'每一项按所选日期、这批玩家中该项最高记录换算为 100，最多对比 3 人。分数不是职业判定或能力评分；下方保留原始数值。'}
const empty=computed(()=>props.tab==='box'?!runtimeRows.value.length:props.tab==='clock'?!props.base.hours.length:props.tab==='sunburst'?!props.base.contributions.some(c=>c.operation==='PLACE'):props.tab==='timeline'?!data.value?.milestones.length:props.tab==='river'?!riverData.value.some(a=>a.raw.some(v=>v!=null&&v>0)):!data.value?.players.length)
</script>
<template><div class="more-charts">
 <p class="chart-help">{{explanations[tab]}}</p><p v-if="busy" role="status">正在整理已有记录…</p><p v-if="error" role="alert">{{error}} <button @click="load">重试</button></p>
 <template v-if="data">
  <label v-if="tab==='box'" class="chart-select">查看指标<select v-model="runtimeMetric"><option v-for="(label,key) in runtimeLabels" :key="key" :value="key">{{label[0]}}</option></select></label>
  <fieldset v-if="tab==='radar'" class="player-picks"><legend>选择玩家（最多 3 位）</legend><label v-for="p in data.players" :key="p.player"><input v-model="chosen" type="checkbox" :value="p.player" :disabled="chosen.length>=3&&!chosen.includes(p.player)"/>{{p.name}}</label></fieldset>
  <p v-if="empty" class="no-extra-data">这段时间没有对应记录。<template v-if="tab==='box'&&runtimeMetric==='host_cpu'">整机 CPU 需要更新采集器至 0.37.0 后才会出现；旧数据不会补造。</template></p>
  <DataChart v-else :key="tab" :option="options??{}" :label="titles[tab]??'扩展图表'" :height="460"/>
  <div v-if="tab==='radar'" class="raw-table"><table><thead><tr><th>玩家</th><th v-for="[,name] in radarAxes" :key="name">{{name}}</th></tr></thead><tbody><tr v-for="p in data.players.filter(p=>chosen.includes(p.player))" :key="p.player"><th>{{p.name}}</th><td v-for="[key] in radarAxes" :key="key">{{(Number(p[key])/(key==='travel'?1000:1)).toLocaleString()}}{{key==='travel'?' 米':' 次'}}</td></tr></tbody></table></div>
  <ol v-if="tab==='timeline'" class="milestones"><li v-for="(e,i) in data.milestones.slice(0,30)" :key="i"><time>{{eventTime(e.at)}}</time><span>{{eventLabels[e.kind]}} · {{e.name}}<template v-if="e.revision"> · 第 {{e.revision}} 阶段</template></span></li></ol>
  <details class="chart-help"><summary>统计依据与限制 · 整理于 {{eventTime(data.generatedAt)}}</summary><p v-for="note in data.notices" :key="note">{{note}}</p></details>
 </template>
</div></template>
<style scoped>
.chart-help{font-size:12px;line-height:1.9;color:#607a6e;margin:14px 0}.chart-select{display:grid;gap:8px;max-width:260px;font-size:13px}.chart-select select{padding:10px;border:1px solid #cde0d4;border-radius:10px;background:#fff}.player-picks{display:flex;flex-wrap:wrap;gap:12px;border:1px solid #d9e7de;border-radius:12px;padding:12px;max-height:170px;overflow:auto}.player-picks label{display:flex;align-items:center;gap:6px;font-size:12px}.player-picks input{width:auto}.no-extra-data{padding:60px 16px;text-align:center;color:#6c8278}.raw-table{overflow:auto;max-width:100%;font-size:12px}.raw-table table{width:100%;border-collapse:collapse}.raw-table td,.raw-table th{padding:10px;border-bottom:1px solid #e5eee8;white-space:nowrap;text-align:left}.milestones{padding:0;list-style:none;max-height:300px;overflow:auto}.milestones li{display:flex;gap:15px;padding:12px;border-bottom:1px solid #e5eee8;font-size:12px}.milestones time{color:#698273;flex-shrink:0}@media(max-width:600px){.milestones li{flex-direction:column;gap:5px}}
</style>
